package de.lazytv.pro.playlist;
import android.content.Context;import android.content.SharedPreferences;import org.json.JSONArray;import org.json.JSONException;import java.util.*;
public class PlaylistStorage {private static final String PREFS="lazytv_playlists",KEY_ITEMS="items",KEY_ACTIVE="active_playlist_id";private final SharedPreferences prefs;public PlaylistStorage(Context context){prefs=context.getSharedPreferences(PREFS,Context.MODE_PRIVATE);}public List<Playlist> getAll(){List<Playlist> result=new ArrayList<>();String raw=prefs.getString(KEY_ITEMS,"[]");try{JSONArray array=new JSONArray(raw);for(int i=0;i<array.length();i++){try{result.add(Playlist.fromJson(array.getJSONObject(i)));}catch(Exception ignored){}}}catch(Exception ignored){return result;}Collections.sort(result,Comparator.comparingLong(Playlist::getUpdatedAt).reversed());return result;}public Playlist get(String id){if(id==null)return null;for(Playlist playlist:getAll())if(id.equals(playlist.getId()))return playlist;return null;}public void save(Playlist item){if(item==null)throw new IllegalArgumentException("Playlist is required");List<Playlist> items=getAll();boolean replaced=false;for(int i=0;i<items.size();i++)if(items.get(i).getId().equals(item.getId())){items.set(i,item);replaced=true;break;}if(!replaced)items.add(item);write(items);}public void delete(String id){if(id==null)return;List<Playlist> items=getAll();for(int i=items.size()-1;i>=0;i--)if(id.equals(items.get(i).getId()))items.remove(i);write(items);if(id.equals(getActiveId()))prefs.edit().remove(KEY_ACTIVE).apply();}public void setActive(String id){if(get(id)==null)throw new IllegalArgumentException("Playlist does not exist");prefs.edit().putString(KEY_ACTIVE,id).apply();}public String getActiveId(){String id=prefs.getString(KEY_ACTIVE,"");return id!=null&&getWithoutActiveLookup(id)!=null?id:"";}private Playlist getWithoutActiveLookup(String id){if(id==null||id.isEmpty())return null;for(Playlist playlist:getAll())if(id.equals(playlist.getId()))return playlist;return null;}private void write(List<Playlist> items){JSONArray array=new JSONArray();try{for(Playlist playlist:items)array.put(playlist.toJson());boolean ok=prefs.edit().putString(KEY_ITEMS,array.toString()).commit();if(!ok)throw new IllegalStateException("Playlist storage write failed");}catch(JSONException e){throw new IllegalStateException("Playlist serialization failed",e);}}}
